#pragma once

#include <stdint.h>

#include "v3_protocol.h"

// AI: below section was generated by an AI

constexpr uint16_t V3_MAX_AUTHORITY_LEASE_DECISECONDS = 600;

struct V3AuthorityState {
  DeviceId authorityId = 0;
  uint32_t authoritySession = 0;
  uint16_t sequence = 0;
  uint32_t leaseExpiresAtMs = 0;
  uint8_t priority = 0;
  uint8_t quality = 0;
  bool active = false;
};

inline bool v3SequenceIsNewer(uint16_t candidate, uint16_t previous) {
  return candidate != previous && int16_t(candidate - previous) > 0;
}

inline bool v3DeadlineReached(uint32_t nowMs, uint32_t deadlineMs) {
  return int32_t(nowMs - deadlineMs) >= 0;
}

class V3AuthorityBook {
  public:
    // Accept a root-authorized declaration and preserve one independent lease per topic.
    bool accept(uint8_t topic, const V3TopicEnvelope& envelope, uint32_t nowMs) {
      if (!isKnownV3Topic(topic)
          || topic == V3TopicPresence
          || (topic == V3TopicPosition && envelope.messageKind == V3Advertisement))
        return true;

      V3AuthorityState& current = states[topic];
      expireOne(current, nowMs);

      if (envelope.messageKind == V3Claim) {
        if (current.active
            && current.authorityId == envelope.authorityId
            && current.authoritySession == envelope.authoritySession
            && !v3SequenceIsNewer(envelope.sequence, current.sequence))
          return false;

        current.authorityId = envelope.authorityId;
        current.authoritySession = envelope.authoritySession;
        current.sequence = envelope.sequence;
        current.priority = envelope.priority;
        current.quality = envelope.quality;
        current.active = true;
        renewLease(current, envelope, nowMs);
        return true;
      }

      if (!matches(current, envelope))
        return false;

      if (envelope.messageKind == V3Release) {
        current = V3AuthorityState();
        return true;
      }

      if (!v3SequenceIsNewer(envelope.sequence, current.sequence))
        return false;

      current.sequence = envelope.sequence;
      current.quality = envelope.quality;
      renewLease(current, envelope, nowMs);
      return true;
    }

    // Record a local claim before transmission because senders do not receive their own broadcast.
    void claimLocal(uint8_t topic, const V3TopicEnvelope& envelope, uint32_t nowMs) {
      if (!isKnownV3Topic(topic) || topic == V3TopicPresence)
        return;
      V3AuthorityState& current = states[topic];
      current.authorityId = envelope.authorityId;
      current.authoritySession = envelope.authoritySession;
      current.sequence = envelope.sequence;
      current.priority = envelope.priority;
      current.quality = envelope.quality;
      current.active = true;
      renewLease(current, envelope, nowMs);
    }

    void expire(uint32_t nowMs) {
      for (uint8_t topic = 0; topic <= V3TopicControl; topic++)
        expireOne(states[topic], nowMs);
    }

    const V3AuthorityState& get(uint8_t topic) const {
      static const V3AuthorityState empty;
      return isKnownV3Topic(topic) ? states[topic] : empty;
    }

    void clear() {
      for (V3AuthorityState& state : states)
        state = V3AuthorityState();
    }

  private:
    V3AuthorityState states[V3TopicControl + 1];

    static bool matches(const V3AuthorityState& current, const V3TopicEnvelope& envelope) {
      return current.active
          && current.authorityId == envelope.authorityId
          && current.authoritySession == envelope.authoritySession;
    }

    static void renewLease(V3AuthorityState& current, const V3TopicEnvelope& envelope, uint32_t nowMs) {
      uint16_t lease = envelope.leaseDeciseconds;
      if (lease == 0 || lease > V3_MAX_AUTHORITY_LEASE_DECISECONDS)
        lease = V3_MAX_AUTHORITY_LEASE_DECISECONDS;
      current.leaseExpiresAtMs = nowMs + uint32_t(lease) * 100;
    }

    static void expireOne(V3AuthorityState& current, uint32_t nowMs) {
      if (current.active && v3DeadlineReached(nowMs, current.leaseExpiresAtMs))
        current = V3AuthorityState();
    }
};

